struct counters {
    _Atomic uint64_t packets;
} __rte_cache_aligned;
static struct counters stats[RTE_MAX_LCORE];

void record_packet(void) {
    struct counters *c = &stats[rte_lcore_id()];
    /* 这一项只有本 lcore 写：relaxed load 加 store 即可 */
    uint64_t n = atomic_load_explicit(&c->packets, memory_order_relaxed);
    atomic_store_explicit(&c->packets, n + 1, memory_order_relaxed);
}

uint64_t read_packet_total(void) {
    uint64_t total = 0;
    /* 运行期无数据竞争；各项来自不同时刻 */
    for (unsigned int i = 0; i < RTE_MAX_LCORE; ++i)
        total += atomic_load_explicit(&stats[i].packets, memory_order_relaxed);
    return total;
}

