static _Atomic(struct route_table *) routes;
/* qs 与初始路由表已初始化，每个读线程已注册 */
void run_worker(void) {
    unsigned int id = rte_lcore_id();
    struct rte_mbuf *packets[BURST_SIZE];
    rte_rcu_qsbr_thread_online(qs, id);
    while (keep_running()) {
        /* 循环中的收包和转发均为非阻塞调用 */
        unsigned int n = receive_burst(packets, BURST_SIZE);
        struct route_table *table = atomic_load_explicit(&routes, memory_order_acquire);
        for (unsigned int i = 0; i < n; ++i)
            forward_using(table, packets[i]);
        /* 本轮结束，后续不再保留 table 的引用 */
        rte_rcu_qsbr_quiescent(qs, id);
    }
    rte_rcu_qsbr_thread_offline(qs, id);
    rte_rcu_qsbr_thread_unregister(qs, id);
}

/* 单一控制线程发布已完整初始化的不可变表 */
void replace_routes(struct route_table *next) {
    struct route_table *old = atomic_exchange_explicit(&routes, next, memory_order_acq_rel);
    rte_rcu_qsbr_synchronize(qs, RTE_QSBR_THRID_INVALID);
    free(old);
}

